-- Create "route_conflict" table
CREATE TABLE "route_conflict" ("id" bigserial NOT NULL, "route_id" bigint NOT NULL, "conflicting_route_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "route_conflict_route_id_conflicting_route_id_key" UNIQUE ("route_id", "conflicting_route_id"), CONSTRAINT "route_conflict_conflicting_route_id_fkey" FOREIGN KEY ("conflicting_route_id") REFERENCES "route" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "route_conflict_route_id_fkey" FOREIGN KEY ("route_id") REFERENCES "route" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "route_conflict_check" CHECK (route_id <> conflicting_route_id));
